from fractions import Fraction


def expected_turns(n: int, m: int, jumps: list[list[int]]) -> list[int] | None:
    jump = {a: b for a, b in jumps}

    def resolve(c: int) -> int:
        while c in jump:
            c = jump[c]
        return c

    def moves(p: int) -> list[int]:
        res = []
        for r in range(1, m + 1):
            q = p + r
            if q > n:
                q = 2 * n - p - r
            res.append(resolve(q))
        return res

    # Cells reachable from the start (after jump resolution).
    start = resolve(0)
    reach = {start}
    stack = [start]
    while stack:
        p = stack.pop()
        if p == n:
            continue
        for q in moves(p):
            if q not in reach:
                reach.add(q)
                stack.append(q)

    # Every reachable cell must be able to reach n, otherwise the game may never end.
    rev = {s: [] for s in reach}
    for p in reach:
        if p == n:
            continue
        for q in moves(p):
            rev[q].append(p)
    good = {n}
    stack = [n]
    while stack:
        q = stack.pop()
        for p in rev[q]:
            if p not in good:
                good.add(p)
                stack.append(p)
    if any(s not in good for s in reach):
        return None

    # Expected-value system over transient (non-terminal) reachable cells:
    # E[p] - sum_{q} (1/m) E[q] = 1, with E[n] = 0.
    trans = [s for s in reach if s != n]
    idx = {s: i for i, s in enumerate(trans)}
    k = len(trans)
    A = [[Fraction(0)] * k for _ in range(k)]
    b = [Fraction(1)] * k
    inv_m = Fraction(1, m)
    for p in trans:
        i = idx[p]
        A[i][i] += 1
        for q in moves(p):
            if q != n:
                A[i][idx[q]] -= inv_m

    # Gauss-Jordan elimination with exact fractions.
    for col in range(k):
        piv = next(r for r in range(col, k) if A[r][col] != 0)
        A[col], A[piv] = A[piv], A[col]
        b[col], b[piv] = b[piv], b[col]
        pv = A[col][col]
        A[col] = [x / pv for x in A[col]]
        b[col] /= pv
        for r in range(k):
            if r != col and A[r][col] != 0:
                f = A[r][col]
                A[r] = [x - f * y for x, y in zip(A[r], A[col])]
                b[r] -= f * b[col]

    ans = b[idx[start]]
    return [ans.numerator, ans.denominator]
